param([string]$Revision='0.1.0')
$ErrorActionPreference='Stop';$expected=@("madlava-agent-$Revision.jar","madlava-report-viewer-$Revision.zip","madlava-$Revision-complete-project.zip")
$files=@($expected|ForEach-Object{Get-Item -LiteralPath (Join-Path target $_) -ErrorAction Stop}|Sort-Object Name);if($files.Count-ne$expected.Count){throw "Expected $($expected.Count) release artifacts"}
$lines=$files|ForEach-Object{"$((Get-FileHash -LiteralPath $_.FullName -Algorithm SHA256).Hash.ToLower())  $($_.Name)"};$path="target/MadLava-$Revision-SHA256SUMS.txt";[IO.File]::WriteAllLines((Join-Path (Get-Location) $path),$lines,(New-Object Text.UTF8Encoding($false)));$java=(Get-Command java).Source;$mvn=(Get-Command mvn -ErrorAction SilentlyContinue).Source;$provenance=[ordered]@{product='MadLava';version=$Revision;java=$java;maven=$mvn;generatedAt=(Get-Date).ToUniversalTime().ToString('o');artifacts=$files|ForEach-Object{[ordered]@{name=$_.Name;bytes=$_.Length;sha256=(Get-FileHash -LiteralPath $_.FullName -Algorithm SHA256).Hash.ToLower()}}};$provenance|ConvertTo-Json -Depth 5|Set-Content -Encoding UTF8 target/MadLava-$Revision-provenance.json;Write-Output $path
